<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { apiRequest, unwrap, type ApiEnvelope } from '../lib/api';
import RichText from './RichText.vue';

type Row = Record<string, unknown>;
const props = defineProps<{ dashboard: Row }>();
const emit = defineEmits<{ updated: [] }>();
const view = ref<'overview' | 'library' | 'insights' | 'automation'>('overview');
const selectedId = ref('');
const watchlistId = ref('');
const keyword = ref('');
const risk = ref('all');
const busy = ref(false);
const error = ref('');
const notice = ref('');
const dryResult = ref<Row | null>(null);
const reports = computed<Row[]>(() => Array.isArray(props.dashboard.latestReports) ? props.dashboard.latestReports as Row[] : []);
const watchlists = computed<Row[]>(() => Array.isArray(props.dashboard.watchlists) ? props.dashboard.watchlists as Row[] : []);
const providers = computed<Row[]>(() => Array.isArray(props.dashboard.providerMatrix) ? props.dashboard.providerMatrix as Row[] : []);
const channels = computed<Row[]>(() => Array.isArray(props.dashboard.notificationChannels) ? props.dashboard.notificationChannels as Row[] : []);
const runs = computed<Row[]>(() => Array.isArray(props.dashboard.recentRuns) ? props.dashboard.recentRuns as Row[] : []);
const deliveries = computed<Row[]>(() => Array.isArray(props.dashboard.recentDeliveries) ? props.dashboard.recentDeliveries as Row[] : []);
const selected = computed(() => reports.value.find(item => item.id === selectedId.value) || reports.value[0] || null);
const filtered = computed(() => reports.value.filter(item => (risk.value === 'all' || item.riskLevel === risk.value) && `${item.title || ''} ${item.summary || ''} ${item.recommendation || ''}`.toLowerCase().includes(keyword.value.toLowerCase())));
const structured = computed<Row>(() => selected.value?.structured && typeof selected.value.structured === 'object' ? selected.value.structured as Row : {});
const candidates = computed<Row[]>(() => Array.isArray(structured.value.candidates) ? structured.value.candidates as Row[] : []);
const risks = computed<string[]>(() => Array.isArray(structured.value.risks) ? structured.value.risks.filter((item): item is string => typeof item === 'string') : []);
const coverage = computed<Row>(() => structured.value.coverage && typeof structured.value.coverage === 'object' ? structured.value.coverage as Row : {});
const evidence = computed<Row[]>(() => Array.isArray(selected.value?.evidence) ? selected.value.evidence as Row[] : []);
const summary = computed<Row>(() => props.dashboard.summary && typeof props.dashboard.summary === 'object' ? props.dashboard.summary as Row : {});
const currentWatchlist = computed(() => watchlists.value.find(item => item.id === watchlistId.value) || watchlists.value[0]);
const liveChannels = computed(() => channels.value.filter(item => !item.isDryRun && item.status === 'active'));
const shownReport = computed(() => selected.value ? String(selected.value.title || selected.value.id) : '尚无报告');
watch(watchlists, items => { if (!items.some(item => item.id === watchlistId.value)) watchlistId.value = String(items[0]?.id || ''); }, { immediate: true });
watch(reports, items => { if (!items.some(item => item.id === selectedId.value)) selectedId.value = String(items[0]?.id || ''); }, { immediate: true });
const date = (value: unknown) => value ? new Date(String(value)).toLocaleString('zh-CN') : '—';
const percent = (value: unknown) => typeof value === 'number' ? `${Math.round(value * 100)}%` : '—';
function openReport(item: Row) { selectedId.value = String(item.id); view.value = 'library'; }

async function act(action: 'run-daily-report' | 'send-latest-report', dryRun: boolean) {
  if (action === 'send-latest-report' && !selected.value) return;
  if (action === 'send-latest-report' && !dryRun) {
    const targets = liveChannels.value.map(item => `${item.name || item.channelType}${item.target ? `（${item.target}）` : ''}`).join('、') || '服务端已配置的通知通道';
    if (!window.confirm(`将真实推送“${shownReport.value}”到：${targets}。确定发送？`)) return;
  }
  busy.value = true; error.value = ''; notice.value = '';
  try {
    const payload = unwrap(await apiRequest<ApiEnvelope<Row>>('/api/research/reports', {
      method: 'POST', body: JSON.stringify({ action, dryRun,
        ...(action === 'run-daily-report' ? { watchlistId: watchlistId.value || undefined } : { reportId: selected.value?.id }),
        ...(dryRun ? {} : { confirmed: true, idempotencyKey: `vue-report-${Date.now()}-${crypto.randomUUID()}` }),
      }),
    }));
    if (dryRun) dryResult.value = payload && typeof payload === 'object' ? payload : {};
    notice.value = dryRun ? '预演完成，未进行真实推送' : action === 'run-daily-report' ? '日报生成请求已提交' : '推送请求已提交';
    emit('updated');
  } catch (cause) { error.value = cause instanceof Error ? cause.message : '操作失败'; }
  finally { busy.value = false; }
}
</script>

<template>
  <div class="reports-workbench">
    <div class="report-tabs" role="tablist" aria-label="投研报告视图"><button v-for="item in [{id:'overview',label:'研究总览'},{id:'library',label:'完整报告'},{id:'insights',label:'主题洞察'},{id:'automation',label:'源与自动化'}]" :key="item.id" type="button" role="tab" :aria-selected="view === item.id" :class="{ active: view === item.id }" @click="view = item.id as typeof view">{{ item.label }}</button></div>
    <p v-if="error" class="inline-error" role="alert">{{ error }}</p><p v-if="notice" class="report-notice">{{ notice }}</p>
    <div v-if="view === 'overview'" class="report-overview">
      <section class="report-feature"><div class="eyebrow">LATEST BRIEF</div><h2>{{ selected ? shownReport : '等待第一份研究报告' }}</h2><p>{{ selected?.summary || '从观察池出发，系统会采样行情与候选标的，再保存研究结论和证据。' }}</p><div v-if="selected" class="report-feature-meta"><span>评分 {{ selected.score ?? '—' }}</span><span>风险 {{ selected.riskLevel || '—' }}</span><span>{{ date(selected.createdAt) }}</span></div><div class="report-feature-actions"><button v-if="selected" class="primary-button" @click="view = 'library'">阅读完整报告 →</button><button v-else class="primary-button" @click="view = 'automation'">检查生成条件 →</button></div></section>
      <section class="paper-panel report-pipeline"><div class="panel-heading"><strong>研究链路</strong><span>{{ runs[0]?.status || '待运行' }}</span></div><ol><li><span>01</span><div><strong>观察范围</strong><small>{{ watchlists.length }} 个观察池 · {{ currentWatchlist?.name || '尚未配置' }}</small></div></li><li><span>02</span><div><strong>证据来源</strong><small>{{ providers.filter(item => item.status === 'available').length }} / {{ providers.length }} 个来源可用</small></div></li><li><span>03</span><div><strong>报告与交付</strong><small>{{ reports.length }} 份报告 · {{ deliveries.length }} 条推送记录</small></div></li></ol></section>
      <section class="paper-panel report-wide"><div class="panel-heading"><strong>研究范围</strong><button type="button" @click="view = 'automation'">查看全部 →</button></div><div class="report-watchlists"><article v-for="item in watchlists" :key="String(item.id)"><strong>{{ item.name }}</strong><p>{{ item.description || '使用当前股票池作为日报观察范围。' }}</p><div class="report-chips"><span v-for="symbol in (item.symbols as string[] || []).slice(0, 8)" :key="symbol">{{ symbol }}</span><span v-if="(item.symbols as string[] || []).length > 8">+{{ (item.symbols as string[]).length - 8 }}</span></div></article><p v-if="!watchlists.length">尚无观察池。先到策略实验室检查股票池和数据。</p></div></section>
    </div>
    <div v-else-if="view === 'library'" class="report-library"><div class="report-library-rail"><div class="report-filter"><input v-model="keyword" aria-label="搜索报告" placeholder="搜索报告标题或建议" /><select v-model="risk" aria-label="风险等级"><option value="all">全部风险</option><option value="low">低风险</option><option value="medium">中风险</option><option value="high">高风险</option></select></div><button v-for="item in filtered" :key="String(item.id)" :class="['report-list-item',{active:selected?.id===item.id}]" @click="openReport(item)"><span>{{ date(item.reportDate || item.createdAt) }}</span><strong>{{ item.title }}</strong><small>{{ item.summary }}</small><em>评分 {{ item.score ?? '—' }} · {{ item.riskLevel || '风险待评估' }}</em></button><p v-if="!filtered.length" class="report-empty">{{ reports.length ? '没有匹配的报告。' : '报告库还没有内容；先在「源与自动化」生成日报。' }}</p></div><article class="paper-panel report-document" v-if="selected"><div class="report-document-head"><div><div class="eyebrow">RESEARCH REPORT</div><h2>{{ selected.title }}</h2><p>{{ date(selected.createdAt) }} · {{ selected.source }}</p></div><strong class="report-score">{{ selected.score ?? '—' }}<small>研究评分</small></strong></div><div class="report-document-lead"><strong>{{ selected.summary }}</strong><p>研究建议：{{ selected.recommendation || '待人工复核' }}</p></div><div class="report-metrics"><div><span>风险等级</span><strong>{{ selected.riskLevel || '—' }}</strong></div><div><span>候选标的</span><strong>{{ candidates.length }}</strong></div><div><span>证据来源</span><strong>{{ evidence.length }}</strong></div><div><span>数据覆盖</span><strong>{{ percent(coverage.coverageRatio) }}</strong></div></div><section v-if="candidates.length"><h3>候选标的</h3><div class="report-candidates"><div v-for="item in candidates" :key="String(item.symbol)"><strong>{{ item.name || item.symbol }}</strong><small>{{ item.symbol }} · {{ item.score == null ? '待评分' : `评分 ${item.score}` }}</small></div></div></section><section><h3>研究正文</h3><RichText :content="String(selected.contentMarkdown || selected.summary || '')" /></section><section v-if="risks.length"><h3>风险与复核</h3><ul class="report-risks"><li v-for="item in risks" :key="item">{{ item }}</li></ul></section><section><h3>证据来源</h3><div class="report-evidence"><div v-for="(item,index) in evidence" :key="index"><strong>{{ item.source }}</strong><span>{{ item.status }}</span><p>{{ item.detail }}</p></div><p v-if="!evidence.length">这份报告没有列出单独的证据条目。</p></div></section><button class="primary-button" :disabled="busy" @click="act('send-latest-report', false)">推送这份报告 →</button></article><section v-else class="paper-panel report-document report-empty"><h2>还没有研究报告</h2><p>完成一次日报生成后，报告正文、候选标的、风险和证据会在这里展开。</p><button class="secondary-button" @click="view = 'automation'">去生成日报</button></section></div>
    <div v-else-if="view === 'insights'" class="report-insights"><section class="paper-panel"><div class="panel-heading"><strong>研究主题</strong><span>{{ reports.length }} 份报告</span></div><div v-for="item in reports.slice(0, 8)" :key="String(item.id)" class="report-insight-row"><div><strong>{{ item.title }}</strong><p>{{ item.summary }}</p></div><button class="secondary-button" @click="openReport(item)">看依据</button></div><p v-if="!reports.length">生成日报后，主题和结论会从真实报告中汇总到这里。</p></section><section class="paper-panel"><div class="panel-heading"><strong>最近一次证据状态</strong></div><div v-for="item in providers" :key="String(item.id)" class="report-provider"><strong>{{ item.name }}</strong><span>{{ item.status }}</span><p>{{ item.detail }}</p></div></section></div>
    <div v-else class="report-automation"><section class="paper-panel"><div class="panel-heading"><strong>生成日报</strong><span>先选观察池，再预演</span></div><p>预演只检查当前数据与流程；生成日报会在本地数据库保存结果。</p><label>观察池<select v-model="watchlistId"><option v-for="item in watchlists" :key="String(item.id)" :value="String(item.id)">{{ item.name }}</option></select></label><div class="report-feature-actions"><button class="secondary-button" :disabled="busy || !watchlistId" @click="act('run-daily-report', true)">预演生成</button><button class="primary-button" :disabled="busy || !watchlistId" @click="act('run-daily-report', false)">生成并保存日报</button></div></section><section class="paper-panel"><div class="panel-heading"><strong>数据来源</strong><span>{{ providers.length }} 项</span></div><div v-for="item in providers" :key="String(item.id)" class="report-provider"><strong>{{ item.name }}</strong><span>{{ item.status }}</span><p>{{ item.detail }}</p></div></section><section class="paper-panel"><div class="panel-heading"><strong>通知通道</strong><span>{{ channels.length }} 项</span></div><div v-for="item in channels" :key="String(item.id)" class="report-provider"><strong>{{ item.name }}</strong><span>{{ item.isDryRun ? '仅预演' : item.status }}</span><p>{{ item.target || item.channelType }}</p></div><button class="secondary-button" :disabled="busy || !selected" @click="act('send-latest-report', true)">预演推送当前报告</button></section><section class="paper-panel"><div class="panel-heading"><strong>最近任务与回执</strong></div><div v-for="item in runs.slice(0, 6)" :key="String(item.id)" class="report-run"><strong>{{ item.runType || '日报任务' }}</strong><span>{{ item.status }}</span><small>{{ date(item.startedAt) }}</small></div><div v-for="item in deliveries.slice(0, 6)" :key="String(item.id)" class="report-run"><strong>{{ item.title || '推送回执' }}</strong><span>{{ item.status }}</span><small>{{ date(item.createdAt) }}</small></div><p v-if="!runs.length && !deliveries.length">还没有运行或推送记录。</p></section><section v-if="dryResult" class="paper-panel report-wide"><div class="panel-heading"><strong>最近预演结果</strong></div><p>{{ (dryResult.summary as Row)?.reports != null ? `报告总数：${(dryResult.summary as Row).reports}` : '预演已返回结果，可刷新查看最新状态。' }}</p></section></div>
  </div>
</template>

<style scoped>
.reports-workbench{margin-top:15px}.report-tabs{display:flex;gap:3px;border-bottom:1px solid #dcded4;margin-bottom:18px;overflow:auto}.report-tabs button{border:0;border-bottom:2px solid transparent;background:transparent;padding:12px 15px;color:#69736b;white-space:nowrap;font-size:12px;font-weight:700}.report-tabs button.active{border-color:#a56e27;color:#263c33}.report-overview{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(280px,.8fr);gap:15px}.report-feature{background:linear-gradient(120deg,#273d34,#40564a);color:white;border-radius:10px;padding:29px;min-height:300px;display:flex;flex-direction:column;align-items:flex-start}.report-feature .eyebrow{color:#e1bc80}.report-feature h2{font:600 27px/1.35 Georgia,'Noto Serif SC',serif;margin:17px 0 9px}.report-feature p{color:#e5e9e0;font-size:13px;line-height:1.8;max-width:620px}.report-feature-meta,.report-chips{display:flex;flex-wrap:wrap;gap:7px}.report-feature-meta span{border:1px solid #819187;border-radius:20px;padding:6px 10px;font-size:11px}.report-feature-actions{display:flex;flex-wrap:wrap;gap:9px;margin-top:auto;padding-top:16px}.report-feature .primary-button{background:#d2a45b;border-color:#d2a45b;color:#263c33}.report-pipeline ol{list-style:none;margin:0;padding:0}.report-pipeline li{display:flex;gap:12px;align-items:center;padding:13px 0;border-bottom:1px solid #e1e3d8}.report-pipeline li>span{font:600 20px Georgia;color:#aa762f}.report-pipeline strong,.report-pipeline small{display:block}.report-pipeline strong{font-size:12px}.report-pipeline small{font-size:11px;color:#69736b;margin-top:3px}.report-wide{grid-column:1/-1}.report-watchlists{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.report-watchlists article{border:1px solid #e1e3d8;border-radius:7px;padding:14px;background:#fff}.report-watchlists strong{font-size:13px}.report-watchlists p,.report-automation p{font-size:12px;color:#69736b;line-height:1.6}.report-chips span{background:#f3eee4;border-radius:4px;padding:4px 6px;font-size:10px}.report-library{display:grid;grid-template-columns:minmax(230px,310px) minmax(0,1fr);gap:14px;align-items:start}.report-library-rail{display:grid;gap:8px;max-height:840px;overflow:auto}.report-filter{display:flex;gap:6px}.report-filter input,.report-filter select,.report-automation select{width:100%;min-width:0;border:1px solid #dcded4;border-radius:6px;padding:9px;background:#fffefa;font-size:12px}.report-list-item{display:grid;gap:6px;text-align:left;border:1px solid #dedfd6;border-radius:7px;background:#fcfbf7;padding:14px}.report-list-item.active{border-color:#af7c37;background:#f7f1e5}.report-list-item span,.report-list-item small,.report-list-item em{font-size:11px;color:#6d776e;font-style:normal}.report-list-item strong{font-size:13px}.report-list-item small{max-height:36px;overflow:hidden}.report-document{min-height:470px}.report-document-head{display:flex;justify-content:space-between;gap:15px;border-bottom:1px solid #e1e3d8;padding-bottom:17px}.report-document-head h2{font:600 24px Georgia,'Noto Serif SC',serif;margin:9px 0}.report-document-head p{font-size:11px;color:#6b766d}.report-score{font:600 30px Georgia;color:#ad772f}.report-score small{display:block;font:11px sans-serif;color:#6b766d}.report-document-lead{background:#f3f0e8;border-left:3px solid #ad772f;padding:15px;margin:19px 0;font-size:13px;line-height:1.7}.report-document-lead p{margin:6px 0 0;color:#69736b}.report-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.report-metrics div{background:#f5f4ee;padding:11px;text-align:center;border-radius:5px}.report-metrics span,.report-metrics strong{display:block}.report-metrics span{font-size:10px;color:#69736b}.report-metrics strong{font-size:17px;margin-top:4px}.report-document section{margin:22px 0}.report-document section h3{font-size:14px;border-bottom:1px solid #e1e3d8;padding-bottom:7px}.report-candidates,.report-evidence{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:9px}.report-candidates div,.report-evidence div{border:1px solid #e1e3d8;border-radius:6px;padding:11px}.report-candidates strong,.report-candidates small{display:block}.report-candidates small,.report-evidence p{font-size:11px;color:#69736b;margin:5px 0 0}.report-risks li{margin:8px 0;font-size:12px;line-height:1.6}.report-evidence span{float:right;font-size:11px;color:#a56e27}.report-empty{padding:25px;color:#69736b;font-size:12px}.report-insights,.report-automation{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.report-insight-row,.report-provider,.report-run{border-bottom:1px solid #e1e3d8;padding:11px 0;font-size:12px}.report-insight-row{display:flex;justify-content:space-between;gap:12px}.report-insight-row p,.report-provider p{color:#69736b;font-size:11px;line-height:1.5;margin:5px 0 0}.report-provider span,.report-run span{float:right;color:#a56e27}.report-run{display:flex;justify-content:space-between;gap:10px}.report-run small{color:#69736b}.report-automation label{display:grid;gap:7px;font-size:12px;font-weight:700}.report-notice{background:#eaf4ec;color:#337453;border-radius:6px;padding:10px;font-size:12px}@media(max-width:820px){.report-overview,.report-library,.report-insights,.report-automation{grid-template-columns:1fr}.report-library-rail{max-height:280px}.report-metrics{grid-template-columns:repeat(2,1fr)}}
</style>
